// find_max returns an index of a maximum element in the non‐empty slice `a`.
#[requires(a.len() > 0)]
#[ensures(result < a.len())]
#[ensures(forall(|j: usize| j < a.len() ==> a[result] >= a[j]))]
fn find_max(a: &[i32]) -> usize {
    let mut max_index = 0;
    let mut max_value = a[0];

    // Loop over i = 1..a.len(), maintaining:
    //   1) max_index < a.len()
    //   2) max_value == a[max_index]
    //   3) for all j < i, a[max_index] >= a[j]
    // and terminating since (a.len() - i) strictly decreases each iteration.
    #[invariant(max_index < a.len())]
    #[invariant(max_value == a[max_index])]
    #[invariant(i < a.len())]
    #[invariant(forall(|j: usize| j < i ==> max_value >= a[j]))]
    #[decreases(a.len() - i)]
    for (i, &value) in a.iter().enumerate().skip(1) {
        if value > max_value {
            max_value = value;
            max_index = i;
        }
    }

    max_index
}

